import {
  createStaticHttpManifestInputFromFileList,
  renderStaticHttpManifestModule,
  scanStaticHttpMiddlewareFiles,
  scanStaticHttpRouteFiles,
} from "../static-http-manifest"
import fs from "fs/promises"
import os from "os"
import path from "path"

describe("renderStaticHttpManifestModule", () => {
  it("renders a typed static HTTP manifest module", () => {
    const manifest = renderStaticHttpManifestModule({
      exportName: "staticHttpManifest",
      generatedBy: "test-generator",
      routes: [
        {
          binding: "productsRoute",
          importPath: "./api/store/products/route",
          route: "/store/products",
          relativePath: "src/api/store/products/route.ts",
        },
      ],
      middlewares: [
        {
          binding: "storeProductRoutesMiddlewares",
          importPath: "./api/store/products/middlewares",
          source: "src/api/store/products/middlewares.ts",
        },
      ],
    })

    expect(manifest).toBe(
      [
        "// Generated by test-generator. Do not edit by hand.",
        'import type { StaticHttpResourceManifest } from "@medusajs/framework/http/static"',
        'import * as productsRoute from "./api/store/products/route"',
        'import { storeProductRoutesMiddlewares } from "./api/store/products/middlewares"',
        "",
        "export const staticHttpManifest = {",
        "  routes: [",
        "    {",
        '      route: "/store/products",',
        "      module: productsRoute,",
        '      relativePath: "src/api/store/products/route.ts",',
        "    },",
        "  ],",
        "  middlewares: [",
        "    {",
        "      module: {",
        "        default: {",
        "          routes: storeProductRoutesMiddlewares,",
        "        },",
        "      },",
        '      source: "src/api/store/products/middlewares.ts",',
        "    },",
        "  ],",
        "} satisfies StaticHttpResourceManifest",
        "",
      ].join("\n")
    )
  })

  it("omits optional route and middleware properties when they are absent", () => {
    const manifest = renderStaticHttpManifestModule({
      exportName: "staticHttpManifest",
      routes: [
        {
          binding: "productsRoute",
          importPath: "./api/store/products/route",
          relativePath: "src/api/store/products/route.ts",
        },
      ],
      middlewares: [
        {
          binding: "storeProductRoutesMiddlewares",
          importPath: "./api/store/products/middlewares",
        },
      ],
    })

    expect(manifest).not.toContain("route:")
    expect(manifest).not.toContain("source:")
    expect(manifest).toContain(
      'relativePath: "src/api/store/products/route.ts"'
    )
  })
})

describe("createStaticHttpManifestInputFromFileList", () => {
  it("derives static HTTP manifest input from route and middleware file paths", () => {
    const input = createStaticHttpManifestInputFromFileList({
      manifestDirectory: "apps/medusa-cloudflare/src/http-proof",
      routeRoot: "packages/medusa/src/api",
      routes: [
        {
          relativePath: "packages/medusa/src/api/store/products/[id]/route.ts",
        },
        {
          relativePath: "apps/medusa-cloudflare/src/http-proof/route.ts",
          route: "/http-proof/:proofId",
          routeRoot: "apps/medusa-cloudflare/src",
        },
      ],
      middlewares: [
        {
          relativePath:
            "packages/medusa/src/api/store/products/middlewares.ts",
          exportName: "storeProductRoutesMiddlewares",
        },
      ],
    })

    expect(input.routes).toEqual([
      {
        binding: "storeProductsByIdRoute",
        importPath:
          "../../../../packages/medusa/src/api/store/products/[id]/route",
        route: "/store/products/:id",
        relativePath: "packages/medusa/src/api/store/products/[id]/route.ts",
      },
      {
        binding: "httpProofRoute",
        importPath: "./route",
        route: "/http-proof/:proofId",
        relativePath: "apps/medusa-cloudflare/src/http-proof/route.ts",
      },
    ])

    expect(input.middlewares).toEqual([
      {
        binding: "storeProductRoutesMiddlewares",
        importPath:
          "../../../../packages/medusa/src/api/store/products/middlewares",
        source: "packages/medusa/src/api/store/products/middlewares.ts",
      },
    ])
  })
})

describe("scanStaticHttpRouteFiles", () => {
  it("scans selected route folders and preserves deterministic file order", async () => {
    const projectRoot = await fs.mkdtemp(
      path.join(os.tmpdir(), "medusa-static-http-")
    )

    try {
      await fs.mkdir(
        path.join(projectRoot, "packages/medusa/src/api/store/products/[id]"),
        { recursive: true }
      )
      await fs.mkdir(
        path.join(projectRoot, "packages/medusa/src/api/admin/plugins"),
        { recursive: true }
      )
      await fs.writeFile(
        path.join(projectRoot, "packages/medusa/src/api/store/products/route.ts"),
        "export const GET = () => {}"
      )
      await fs.writeFile(
        path.join(
          projectRoot,
          "packages/medusa/src/api/store/products/[id]/route.ts"
        ),
        "export const GET = () => {}"
      )
      await fs.writeFile(
        path.join(
          projectRoot,
          "packages/medusa/src/api/admin/plugins/route.ts"
        ),
        "export const GET = () => {}"
      )
      await fs.writeFile(
        path.join(
          projectRoot,
          "packages/medusa/src/api/store/products/not-a-route.ts"
        ),
        "export const GET = () => {}"
      )

      await expect(
        scanStaticHttpRouteFiles({
          projectRoot,
          folders: [
            {
              relativePath: "packages/medusa/src/api/store/products",
              routeRoot: "packages/medusa/src/api",
            },
            {
              relativePath: "packages/medusa/src/api/admin/plugins",
              routeRoot: "packages/medusa/src/api",
            },
          ],
        })
      ).resolves.toEqual([
        {
          relativePath: "packages/medusa/src/api/store/products/route.ts",
          routeRoot: "packages/medusa/src/api",
        },
        {
          relativePath: "packages/medusa/src/api/store/products/[id]/route.ts",
          routeRoot: "packages/medusa/src/api",
        },
        {
          relativePath: "packages/medusa/src/api/admin/plugins/route.ts",
          routeRoot: "packages/medusa/src/api",
        },
      ])
    } finally {
      await fs.rm(projectRoot, { force: true, recursive: true })
    }
  })
})

describe("scanStaticHttpMiddlewareFiles", () => {
  it("scans selected middleware folders and discovers the MiddlewareRoute export", async () => {
    const projectRoot = await fs.mkdtemp(
      path.join(os.tmpdir(), "medusa-static-http-")
    )

    try {
      await fs.mkdir(
        path.join(projectRoot, "packages/medusa/src/api/store/products"),
        { recursive: true }
      )
      await fs.writeFile(
        path.join(
          projectRoot,
          "packages/medusa/src/api/store/products/middlewares.ts"
        ),
        [
          'import { type MiddlewareRoute } from "@medusajs/framework/http"',
          "export const storeProductRoutesMiddlewares: MiddlewareRoute[] = []",
          "",
        ].join("\n")
      )

      await expect(
        scanStaticHttpMiddlewareFiles({
          projectRoot,
          folders: [
            {
              relativePath: "packages/medusa/src/api/store/products",
            },
          ],
        })
      ).resolves.toEqual([
        {
          relativePath: "packages/medusa/src/api/store/products/middlewares.ts",
          exportName: "storeProductRoutesMiddlewares",
        },
      ])
    } finally {
      await fs.rm(projectRoot, { force: true, recursive: true })
    }
  })

  it("rejects middleware files without one clear MiddlewareRoute export", async () => {
    const projectRoot = await fs.mkdtemp(
      path.join(os.tmpdir(), "medusa-static-http-")
    )

    try {
      await fs.mkdir(
        path.join(projectRoot, "packages/medusa/src/api/store/products"),
        { recursive: true }
      )
      await fs.writeFile(
        path.join(
          projectRoot,
          "packages/medusa/src/api/store/products/middlewares.ts"
        ),
        "export const notRoutes = []"
      )

      await expect(
        scanStaticHttpMiddlewareFiles({
          projectRoot,
          folders: [
            {
              relativePath: "packages/medusa/src/api/store/products",
            },
          ],
        })
      ).rejects.toThrow("Expected exactly one exported MiddlewareRoute[]")
    } finally {
      await fs.rm(projectRoot, { force: true, recursive: true })
    }
  })
})
